#include <iostream>
int main() {
    int a[] = {4, 9, 2, 7};
    int target = 2, pos = -1;
    for (int i = 0; i < 4; i++)
        if (a[i] == target) { pos = i; break; }
    std::cout << pos << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {1, 3, 5, 7, 9};
    int low = 0, high = 4, target = 7;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (a[mid] == target) { std::cout << mid; return 0; }
        if (a[mid] < target) low = mid + 1; else high = mid - 1;
    }
    std::cout << -1;
    return 0;
}

