#include <iostream>
int main() {
    int a[] = {1, 3, 5, 7};
    int low = 0, high = 3, target = 7, found = -1;
    while (low < high) {
        int mid = (low + high) / 2;
        if (a[mid] == target) { found = mid; break; }
        else if (a[mid] < target) low = mid + 1; else high = mid - 1;
    }
    std::cout << found << "\n";
    return 0;
}

