#include <iostream>
int main() {
    int a[] = {1, 2, 4, 4, 4, 9};
    int low = 0, high = 5, ans = -1, target = 4;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (a[mid] >= target) { if (a[mid] == target) ans = mid; high = mid - 1; }
        else low = mid + 1;
    }
    std::cout << ans << "\n";
    return 0;
}

